<?php
/**
 * Frontend icon rendering for Pointwise Summary.
 *
 * @package PointwiseSummary
 */

namespace PointwiseSummary\Frontend;

use PointwiseSummary\Helpers\SingletonTrait;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class IconLibrary {

	use SingletonTrait;

	/**
	 * Render an icon for a model or social network.
	 *
	 * @param string $id Icon identifier.
	 * @return string
	 */
	public function render_icon( $id ) {
		$id    = sanitize_key( (string) $id );
		$icons = $this->get_icon_map();

		if ( isset( $icons[ $id ] ) ) {
			return $this->wrap_svg( $icons[ $id ], $id );
		}

		return $this->wrap_letter_badge( $id );
	}

