	/**
	 * Wrap raw SVG markup in the frontend icon span.
	 *
	 * @param string $svg SVG markup.
	 * @param string $slug Icon slug.
	 * @return string
	 */
	private function wrap_svg( $svg, $slug ) {
		return sprintf(
			'<span class="pointwise-summary-icon pointwise-summary-icon-%s" aria-hidden="true">%s</span>',
			esc_attr( $slug ),
			$svg
		);
	}

	/**
	 * Fallback badge for unknown ids.
	 *
	 * @param string $id Icon identifier.
	 * @return string
	 */
	private function wrap_letter_badge( $id ) {
		$letter = strtoupper( substr( $id, 0, 1 ) );

		return sprintf(
			'<span class="pointwise-summary-icon pointwise-summary-icon-fallback" data-letter="%s" aria-hidden="true"></span>',
			esc_attr( $letter )
		);
	}
}
